int firstNonzero(IntegerVector x, int nThread = 1) {
  R_xlen_t N = x.length();
  int out = N;
#pragma omp parallel for num_threads(nThread) reduction(min : out)
  for (R_xlen_t i = 0; i < N; ++i) {
    if (x[i] != 0) {
      out = (i < out) ? i : out;
    }
  }
  return out;
}


