I am trying to implement a procedure in parallel processing form with OpenMP. It contains four level nested for loops (dependent) and has a variable sum_p to be updated in the innermost loop. In short, the my question is regarding the parallel implementation of the following code snippet: for (int i = (test_map.size() - 1); i >= 1; --i) {
     bin_i = test_map.at(i); //test_map is a "STL map of vectors"
     len_rank_bin_i = bin_i.size(); // bin_i is a vector
     for (int j = (i - 1); j >= 0; --j) {
             bin_j = test_map.at(j);
             len_rank_bin_j = bin_j.size();
             for (int u_i = 0; u_i < len_rank_bin_i; u_i++) {
                     node_u = bin_i[u_i]; //node_u is a scalar
                     for (int v_i = 0; v_i < len_rank_bin_j; v_i++) {
                             node_v = bin_j[v_i];
                             if (node_u> node_v)
                                     sum_p += 1;
                     }
             }
     }
} The full program is given below: #include <iostream>
#include <vector>
#include <omp.h>
#include <random>
#include <unordered_map>
#include <algorithm>
#include <functional>
#include <time.h>

int main(int argc, char* argv[]){
    double time_temp;
    int test_map_size = 5000;
    std::unordered_map<unsigned int, std::vector<unsigned int> > test_map(test_map_size);

    // Fill the test map with random intergers ---------------------------------
    std::random_device rd;
    std::mt19937 gen1(rd());
    std::uniform_int_distribution<int> dist(1, 5);
    auto gen = std::bind(dist, gen1);
    for(int i = 0; i < test_map_size; i++)
    {
        int vector_len = dist(gen1);
        std::vector<unsigned int> tt(vector_len);
        std::generate(begin(tt), end(tt), gen);
        test_map.insert({i,tt});
    }
    // Sequential implementation -----------------------------------------------
    time_temp = omp_get_wtime();
    std::vector<unsigned int> bin_i, bin_j;
    unsigned int node_v, node_u;
    unsigned int len_rank_bin_i;
    unsigned int len_rank_bin_j;
    int sum_s = 0;
    for (unsigned int i = (test_map_size - 1); i >= 1; --i) {
        bin_i = test_map.at(i);
        len_rank_bin_i = bin_i.size();
        for (unsigned int j = i; j-- > 0; ) {
            bin_j = test_map.at(j);
            len_rank_bin_j = bin_j.size();
            for (unsigned int u_i = 0; u_i < len_rank_bin_i; u_i++) {
                node_u = bin_i[u_i];
                for (unsigned int v_i = 0; v_i < len_rank_bin_j; v_i++) {
                    node_v = bin_j[v_i];
                    if (node_u> node_v)
                        sum_s += 1;
                }
            }
        }
    }
    std::cout<<"Estimated sum (seq): "<<sum_s<<std::endl;
    time_temp = omp_get_wtime() - time_temp;
    printf("Time taken for sequential implementation: %.2fs\n", time_temp);

    // Parallel implementation -----------------------------------------------
    time_temp = omp_get_wtime();
    int sum_p = 0;
    omp_set_num_threads(4);
    #pragma omp parallel
    {
        std::vector<unsigned int> bin_i, bin_j;
        unsigned int node_v, node_u;
        unsigned int len_rank_bin_i;
        unsigned int len_rank_bin_j;
        unsigned int i, u_i, v_i;
        int j;
        #pragma omp parallel for private(j,u_i,v_i) reduction(+:sum_p)
        for (i = (test_map_size - 1); i >= 1; --i) {
            bin_i = test_map.at(i);
            len_rank_bin_i = bin_i.size();
            #pragma omp parallel for private(u_i,v_i)
            for (j = (i - 1); j >= 0; --j) {
                bin_j = test_map.at(j);
                len_rank_bin_j = bin_j.size();
                #pragma omp parallel for private(v_i)
                for (u_i = 0; u_i < len_rank_bin_i; u_i++) {
                    node_u = bin_i[u_i];
                    #pragma omp parallel for
                    for (v_i = 0; v_i < len_rank_bin_j; v_i++) {
                        node_v = bin_j[v_i];
                        if (node_u> node_v)
                            sum_p += 1;
                    }
                }
            }
        }
    }
    std::cout<<"Estimated sum (parallel): "<<sum_p<<std::endl;
    time_temp = omp_get_wtime() - time_temp;
    printf("Time taken for parallel implementation: %.2fs\n", time_temp);
    return 0;
} Running the code with command g++-7 -fopenmp -std=c++11 -O3  -Wall  -o so_qn so_qn.cpp in macOS 10.13.3 (i5 processor with four logical cores) gives the following output: Estimated sum (seq): 38445750
Time taken for sequential implementation: 0.49s
Estimated sum (parallel): 38445750
Time taken for parallel implementation: 50.54s The time taken for parallel implementation is multiple times higher than sequential implementation. Do you think the code or logic can deduced to parallel implementation? I have spent a few days to improve the terrible performance of my code but to no avail. Any help is greatly appreciated. Update With the changes suggested by JimCownie, i.e., "using omp for, not omp parallel for" and removing the parellelism of inner loops, the performance is greatly improved. Estimated sum (seq): 42392944
Time taken for sequential implementation: 0.48s
Estimated sum (parallel): 42392944
Time taken for parallel implementation: 0.27s My CPU has four logical cores (and I am using four threads), now I am wondering, would there be anyway to get four times better performance than the sequential implementation. I see a different problem here when my map of vectors test_map is short, but fat at each level, i.e., the map size is small and but the vector size at each of the keys is very large. In such a case the performance of sequential and parallel implementations are comparable, without much difference. It seems like we need to parallelize inner loops too. Do you know how to achieve it in this context?

I have a fixed-size 2D matrix with size W x H, each element in the matrix is a std::vector. The data is stored in vector of vectors with linearized index. I'm trying to find a way to concurrently fill the output vector. Here is some code to indicate what I'm trying to do. #include <cmath>
#include <chrono>
#include <iostream>
#include <mutex>
#include <vector>
#include <omp.h>

struct Vector2d
{
    double x;
    double y;
};

double generate(double range_min, double range_max)
{
    double val = (double)rand() / RAND_MAX;
    return range_min + val * (range_max - range_min);
}

int main(int argc, char** argv)
{
    (void)argc;
    (void)argv;

    // generate input data
    std::vector<Vector2d> points;
    size_t num = 10000000;
    size_t w = 100;
    size_t h = 100;

    for (size_t i = 0; i < num; ++i)
    {
        Vector2d point;
        point.x = generate(0, w);
        point.y = generate(0, h);
        points.push_back(point);
    }

    // output
    std::vector<std::vector<Vector2d> > output(num, std::vector<Vector2d>());
    std::mutex mutex;

    auto start = std::chrono::system_clock::now();

    #pragma omp parallel for
    for (size_t i = 0; i < num; ++i)
    {
        const Vector2d point = points[i];
        size_t x = std::floor(point.x);
        size_t y = std::floor(point.y);
        size_t id = y * w + x;
        mutex.lock();
        output[id].push_back(point);
        mutex.unlock();
    }

    auto end = std::chrono::system_clock::now();
    std::chrono::duration<double> elapsed_seconds = end - start;
    std::cout << "elapsed time: " << elapsed_seconds.count() << "s\n";

    return 0;
} The problem is the code is much slower with openmp enabled. I found some example to fill std::vector using reduction, but I don't know how to adapt it to vector of vectors. Any help is appreciate, thanks!

answers.body:
There are some things you could do to improve the performance: I would preallocate the second vector holding the Vector2d class, because every time you push_back a new Vector2d and the capacity of the std::vector is exceeded, it is going to reallocate. So if you do not care having initialized Vector2d s in your std::vector I would simply use: std::vector<std::vector<Vector2d> > output(num, 
               std::vector<Vector2d>(num, Vector2d(/*whatever goes in here*/))); Then in your for loop, you coul access the elements in the second vector via operator[] , which allows you to get rid of the lock. #pragma omp parallel for
for (size_t i = 0; i < num; ++i)
{
    const Vector2d point = points[i];
    size_t x = std::floor(point(0));
    size_t y = std::floor(point(1));
    size_t id = y * w + x;
    output[id][i] = num;
} Though I'm not sure, the before-mentioned way works with what you want to do. Otherwise you could reserve the storage for each std::vector<Vector2d> , which would leave you with your initial loop: std::vector<std::vector<Vector2d> > output(num, std::vector<Vector2d>());
for(int i = 0; i < num; ++i) {
    output[i].reserve(num);
}

#pragma omp parallel for
for (size_t i = 0; i < num; ++i)
{
    const Vector2d point = points[i];
    size_t x = std::floor(point(0));
    size_t y = std::floor(point(1));
    size_t id = y * w + x;
    mutex.lock();
    output[id].push_back(point);
    mutex.unlock();
} Which means you get rid of the vector re-allocation, but you still have the mutex...

