void testScaling( )
{
  int N = 1000000; ///total num matrices
  int dim = 10;

  //memory for matrices
  std::vector<xnode> nodeArray(N);
  for( int k = 0; k < N; ++k )
    nodeArray[k].mat = new float [dim*dim];

