export CPATH=/opt/homebrew/Cellar/open-mpi/4.1.2/include The setup.py must specify extra_compile_args and extra_link_args : setup(
    ext_modules = cythonize([
        Extension(
            'foo',
            ['foo.pyx'],
            extra_compile_args=['-fopenmp'],
            extra_link_args=['-lmpi', '-lomp'],
        )
    ]
) Here is a full MWE .

