    for (i = 0; i < jobs; i++) {
        sessions[i] = libssh2_session_init();
        ...
        #pragma omp task
        {
            known = load_known_hosts(sessions[i], ...);
        }

        #pragma omp taskwait
        check_known_hosts(known, ...);
