    movq    %rdi, -8(%rbp)  # .omp_data_i, .omp_data_i

### get the lock id and call omp_set_lock
# lock+volatile.cc:18:             omp_set_lock(&lock);
    movq    -8(%rbp), %rax  # .omp_data_i, tmp87
    movq    (%rax), %rax    # .omp_data_i_2(D)->lock, _3
    movq    %rax, %rdi  # _3,
