### get the lock id and call unset_lock
# lock+volatile.cc:20:             omp_unset_lock(&lock);
    movq    -8(%rbp), %rax  # .omp_data_i, tmp89
    movq    (%rax), %rax    # .omp_data_i_2(D)->lock, _12
    movq    %rax, %rdi  # _12,
    call    omp_unset_lock  # As you can see, in the first case, getting the value of i in the register is performed before the omp_set_lock call. Only using atomic (even with relaxed consistency) have I managed to move it to the “expected” place, presumably because then the access can not be reordered with respect to the lock.

